const input = $input.first().json || {};

let lead = input.normalized_lead || {};

if (typeof lead === "string") {
  lead = JSON.parse(lead);
}

function clean(value) {
  if (value === undefined || value === null) return null;
  const text = String(value).trim();
  return text.length ? text : null;
}

function lower(value) {
  const text = clean(value);
  return text ? text.toLowerCase() : null;
}

const eventId = Number(input.event_id || input.run_id);

if (!eventId) {
  throw new Error("Missing event_id/run_id from Workflow 01");
}

const externalId =
  clean(input.external_id) ||
  clean(lead.external_id) ||
  `${clean(input.event_source || lead.source || "unknown")}:${clean(lead.source_event_id || eventId)}`;

const email = lower(lead.email);

const fullName =
  clean(lead.full_name) ||
  [clean(lead.first_name), clean(lead.last_name)].filter(Boolean).join(" ") ||
  null;

if (!externalId) {
  throw new Error("Missing external_id for lead deduplication");
}

if (!email && !fullName && !lead.company_name) {
  throw new Error("Lead must contain at least email, name, or company_name");
}

return [
  {
    json: {
      run_id: eventId,
      event_id: eventId,
      external_id: externalId,
      event_source: clean(input.event_source || lead.source) || "website_form",

      lead_name: fullName,
      lead_email: email,
      lead_phone: clean(lead.phone),
      lead_source: clean(input.event_source || lead.source) || "website_form",

      company_name: clean(lead.company_name),
      company_domain: clean(lead.company_domain),
      website_url: clean(lead.website_url),
      job_title: clean(lead.job_title),
      message: clean(lead.message),
      budget: clean(lead.budget),
      timeline: clean(lead.timeline),
      country: clean(lead.country),

      normalized_lead: lead
    }
  }
];

const leadRow = $input.first().json;
const original = $('Normalize Deduplication Input').first().json;

const deduplication = {
  lead_id: leadRow.internal_id,
  event_id: original.event_id,
  external_id: leadRow.external_id,
  lead_email: leadRow.lead_email,
  lead_name: leadRow.lead_name,
  dedupe_key_used: original.lead_email ? "lead_email" : "external_id",
  lead_status: leadRow.status
};

return [
  {
    json: {
      ...original,

      lead_id: leadRow.internal_id,
      lead_row: leadRow,
      deduplication
    }
  }
];
